		case constant.Debian, constant.Raspbian, constant.Ubuntu, constant.Windows:
			return xerrors.Errorf("Failed to detect CVEs with gost: %w", err)
		default:
			return xerrors.Errorf("Failed to detect unfixed CVEs with gost: %w", err)
		}
	}
